import { dict, finder } from './dict.js';
import { MORE_SPELLS, EXTRA_CLASS_SPELLS } from './spellsMore.js';

// time: action, bonus, reaction, minute, 10min, hour, 24h (the last four cannot be cast in combat)
// range: feet, 'self' or 'touch'; effect.type picks the engine handler in spellcasting.js
const sp = (name, level, school, classes, effect, o = {}) => ({
  name, level, school, classes, time: 'action', range: 60, components: ['V', 'S'], duration: 'Instantaneous', concentration: false, ritual: false, ...o, effect,
});
const conc = duration => ({ concentration: true, duration: `Concentration, up to ${duration}` });

