const CLERIC = 'cleric';
const DRUID = 'druid';
const PALADIN = 'paladin';
const RANGER = 'ranger';
const SORC = 'sorcerer';
const WARLOCK = 'warlock';
const WIZ = 'wizard';

const BPS = ['bludgeoning', 'piercing', 'slashing'];
const ALL_SAVES = ['str', 'dex', 'con', 'int', 'wis', 'cha'];
const utility = { type: 'utility' };

