  holdPerson: sp('Hold Person', 2, 'enchantment', [BARD, CLERIC, DRUID, SORC, WARLOCK, WIZ], { type: 'save', save: 'wis', creatureType: ['humanoid'], upcastTargets: 1, onFail: { name: 'Hold Person', conditions: ['paralyzed'], saveEnds: 'wis', rounds: 10 } }, { components: ['V', 'S', 'M'], ...conc('1 minute'), desc: 'A humanoid makes a Wisdom save or is paralyzed, repeating the save each turn.' }),
  invisibility: sp('Invisibility', 2, 'illusion', [BARD, SORC, WARLOCK, WIZ], { type: 'buff', upcastTargets: 1, effect: { name: 'Invisibility', conditions: ['invisible'], endsOnAttack: true, minutes: 60 } }, { range: 'touch', components: ['V', 'S', 'M'], ...conc('1 hour'), desc: 'A creature turns invisible until it attacks or casts a spell.' }),
  knock: sp('Knock', 2, 'transmutation', [BARD, SORC, WIZ], utility, { components: ['V'], desc: 'A locked door, chest or shackle unlocks with a loud knock; a magical lock is suppressed.' }),
  lesserRestoration: sp('Lesser Restoration', 2, 'abjuration', [BARD, CLERIC, DRUID, PALADIN, RANGER], { type: 'cleanse', conditions: ['blinded', 'deafened', 'paralyzed', 'poisoned'] }, { range: 'touch', desc: 'End one disease or the blinded, deafened, paralyzed or poisoned condition.' }),
  locateObject: sp('Locate Object', 2, 'divination', [BARD, DRUID, PALADIN, RANGER, WIZ], utility, { range: 'self', components: ['V', 'S', 'M'], ...conc('10 minutes'), desc: 'Sense the direction of a familiar object within 1,000 feet.' }),
  magicWeapon: sp('Magic Weapon', 2, 'transmutation', [PALADIN, WIZ], { type: 'buff', effect: { name: 'Magic Weapon', attackBonus: 1, minutes: 60 } }, { time: 'bonus', range: 'touch', ...conc('1 hour'), desc: 'A nonmagical weapon becomes a magic weapon with a +1 bonus to attack rolls.' }),
  mirrorImage: sp('Mirror Image', 2, 'illusion', [SORC, WARLOCK, WIZ], { type: 'buff', self: true, effect: { name: 'Mirror Image', mirrorImages: 3, rounds: 10 } }, { range: 'self', duration: '1 minute', desc: 'Three illusory duplicates may take attacks meant for you.' }),
  mistyStep: sp('Misty Step', 2, 'conjuration', [SORC, WARLOCK, WIZ], { type: 'teleport', distance: 30 }, { time: 'bonus', range: 'self', components: ['V'], desc: 'Teleport up to 30 feet to an unoccupied space you can see.' }),
  moonbeam: sp('Moonbeam', 2, 'evocation', [DRUID], { type: 'zone', area: { shape: 'cylinder', size: 5 }, save: 'con', damage: { dice: '2d10', type: 'radiant' }, halfOnSave: true, upcastDice: '1d10', rounds: 10 }, { range: 120, components: ['V', 'S', 'M'], ...conc('1 minute'), desc: 'A beam of moonlight: creatures entering or starting there make Constitution saves against 2d10 radiant damage.' }),
  passWithoutTrace: sp('Pass without Trace', 2, 'abjuration', [DRUID, RANGER], { type: 'buff', partyRadius: 30, effect: { name: 'Pass without Trace', skillBonus: { stealth: 10 }, minutes: 60 } }, { range: 'self', components: ['V', 'S', 'M'], ...conc('1 hour'), desc: 'You and companions within 30 feet gain +10 to Stealth checks.' }),
  prayerOfHealing: sp('Prayer of Healing', 2, 'evocation', [CLERIC], { type: 'heal', targets: 6, heal: { dice: '2d8', addMod: true }, upcastDice: '1d8' }, { time: '10min', range: 30, components: ['V'], desc: 'Up to six creatures regain 2d8 + your spellcasting modifier hit points.' }),
  protectionFromPoison: sp('Protection from Poison', 2, 'abjuration', [CLERIC, DRUID, PALADIN, RANGER], { type: 'buff', effect: { name: 'Protection from Poison', resistances: ['poison'], minutes: 60 } }, { range: 'touch', duration: '1 hour', desc: 'The target resists poison damage and has advantage against being poisoned.' }),
  scorchingRay: sp('Scorching Ray', 2, 'evocation', [SORC, WIZ], { type: 'attack', rays: 3, upcastRays: 1, damage: { dice: '2d6', type: 'fire' } }, { range: 120, desc: 'Three rays of fire, each a ranged spell attack for 2d6 fire damage.' }),
  seeInvisibility: sp('See Invisibility', 2, 'divination', [BARD, SORC, WIZ], utility, { range: 'self', components: ['V', 'S', 'M'], duration: '1 hour', desc: 'You see invisible creatures and objects.' }),
  shatter: sp('Shatter', 2, 'evocation', [BARD, SORC, WARLOCK, WIZ], { type: 'save', save: 'con', area: { shape: 'sphere', size: 10 }, damage: { dice: '3d8', type: 'thunder' }, halfOnSave: true, upcastDice: '1d8' }, { components: ['V', 'S', 'M'], desc: 'A ringing noise in a 10-foot radius: Constitution save, 3d8 thunder damage or half.' }),
  silence: sp('Silence', 2, 'illusion', [BARD, CLERIC, RANGER], utility, { range: 120, ...conc('10 minutes'), ritual: true, desc: 'No sound can be created within a 20-foot radius sphere.' }),
  spiderClimb: sp('Spider Climb', 2, 'transmutation', [SORC, WARLOCK, WIZ], { type: 'buff', effect: { name: 'Spider Climb', minutes: 60 } }, { range: 'touch', components: ['V', 'S', 'M'], ...conc('1 hour'), desc: 'The target can climb walls and ceilings with its hands free.' }),
  spiritualWeapon: sp('Spiritual Weapon', 2, 'evocation', [CLERIC], { type: 'spiritualWeapon', damage: { dice: '1d8', type: 'force' }, upcastDicePer2: true }, { time: 'bonus', duration: '1 minute', desc: 'A floating weapon makes a melee spell attack for 1d8 + modifier force damage, and again as a bonus action on later turns.' }),
  suggestion: sp('Suggestion', 2, 'enchantment', [BARD, SORC, WARLOCK, WIZ], { type: 'save', save: 'wis', onFail: { name: 'Suggestion', conditions: ['charmed'], minutes: 480 } }, { range: 30, components: ['V', 'M'], ...conc('8 hours'), desc: 'A creature makes a Wisdom save or pursues a reasonable course of action you suggest.' }),
  web: sp('Web', 2, 'conjuration', [SORC, WIZ], { type: 'save', save: 'dex', area: { shape: 'cube', size: 20 }, onFail: { name: 'Webbed', conditions: ['restrained'], escape: { ability: 'str' }, rounds: 10 } }, { components: ['V', 'S', 'M'], ...conc('1 hour'), desc: 'Sticky webs fill a 20-foot cube: Dexterity save or restrained until it breaks free.' }),
  zoneOfTruth: sp('Zone of Truth', 2, 'enchantment', [BARD, CLERIC, PALADIN], utility, { duration: '10 minutes', desc: 'Creatures in a 15-foot radius that fail a Charisma save cannot deliberately lie.' }),

