  bestowCurse: sp('Bestow Curse', 3, 'necromancy', [BARD, CLERIC, WIZ], { type: 'save', save: 'wis', onFail: { name: 'Bestow Curse', bonusDamageFromCaster: { dice: '1d8', type: 'necrotic' }, rounds: 10 } }, { range: 'touch', ...conc('1 minute'), desc: 'A creature makes a Wisdom save or is cursed: your attacks against it deal an extra 1d8 necrotic damage.' }),
  blink: sp('Blink', 3, 'transmutation', [SORC, WIZ], { type: 'buff', self: true, effect: { name: 'Blink', attackedWithDisadvantage: true, rounds: 10 } }, { range: 'self', duration: '1 minute', desc: 'You flicker into the Ethereal Plane, making you hard to hit.' }),
  callLightning: sp('Call Lightning', 3, 'conjuration', [DRUID], { type: 'save', save: 'dex', area: { shape: 'sphere', size: 5 }, damage: { dice: '3d10', type: 'lightning' }, halfOnSave: true, upcastDice: '1d10' }, { range: 120, ...conc('10 minutes'), desc: 'A bolt from a storm cloud: Dexterity save, 3d10 lightning damage or half.' }),
  counterspell: sp('Counterspell', 3, 'abjuration', [SORC, WARLOCK, WIZ], utility, { time: 'reaction', components: ['S'], desc: 'Interrupt a creature casting a spell; spells of 3rd level or lower fail.' }),
  daylight: sp('Daylight', 3, 'evocation', [CLERIC, DRUID, PALADIN, RANGER, SORC], utility, { duration: '1 hour', desc: 'A 60-foot-radius sphere of bright light dispels magical darkness of 3rd level or lower.' }),
  dispelMagic: sp('Dispel Magic', 3, 'abjuration', [BARD, CLERIC, DRUID, PALADIN, SORC, WARLOCK, WIZ], { type: 'dispel' }, { range: 120, desc: 'End spells of 3rd level or lower on a target; higher ones need an ability check.' }),
  fear: sp('Fear', 3, 'illusion', [BARD, SORC, WARLOCK, WIZ], { type: 'save', save: 'wis', area: { shape: 'cone', size: 30 }, onFail: { name: 'Frightened', conditions: ['frightened'], saveEnds: 'wis', rounds: 10 } }, { range: 'self', components: ['V', 'S', 'M'], ...conc('1 minute'), desc: 'Creatures in a 30-foot cone make Wisdom saves or drop what they hold and are frightened.' }),
  fireball: sp('Fireball', 3, 'evocation', [SORC, WIZ], { type: 'save', save: 'dex', area: { shape: 'sphere', size: 20 }, damage: { dice: '8d6', type: 'fire' }, halfOnSave: true, upcastDice: '1d6' }, { range: 150, components: ['V', 'S', 'M'], desc: 'An explosion of flame in a 20-foot radius: Dexterity save, 8d6 fire damage or half.' }),
  fly: sp('Fly', 3, 'transmutation', [SORC, WARLOCK, WIZ], { type: 'buff', upcastTargets: 1, effect: { name: 'Fly', minutes: 10 } }, { range: 'touch', components: ['V', 'S', 'M'], ...conc('10 minutes'), desc: 'The target gains a flying speed of 60 feet.' }),
  haste: sp('Haste', 3, 'transmutation', [SORC, WIZ], { type: 'buff', effect: { name: 'Haste', acBonus: 2, speedMultiplier: 2, extraAction: true, dexSaveAdvantage: true, lethargyOnEnd: true, rounds: 10 } }, { range: 30, components: ['V', 'S', 'M'], ...conc('1 minute'), desc: 'Double speed, +2 AC, advantage on Dexterity saves and an extra limited action; lethargy when it ends.' }),
  hypnoticPattern: sp('Hypnotic Pattern', 3, 'illusion', [BARD, SORC, WARLOCK, WIZ], { type: 'save', save: 'wis', area: { shape: 'cube', size: 30 }, onFail: { name: 'Hypnotized', conditions: ['incapacitated'], speedZero: true, endsOnDamage: true, rounds: 10 } }, { range: 120, components: ['S', 'M'], ...conc('1 minute'), desc: 'A twisting pattern of colors: Wisdom save or charmed, incapacitated and speed 0 until damaged.' }),
  lightningBolt: sp('Lightning Bolt', 3, 'evocation', [SORC, WIZ], { type: 'save', save: 'dex', area: { shape: 'line', size: 100 }, damage: { dice: '8d6', type: 'lightning' }, halfOnSave: true, upcastDice: '1d6' }, { range: 'self', components: ['V', 'S', 'M'], desc: 'A 100-foot line of lightning: Dexterity save, 8d6 lightning damage or half.' }),
  massHealingWord: sp('Mass Healing Word', 3, 'evocation', [CLERIC], { type: 'heal', targets: 6, heal: { dice: '1d4', addMod: true }, upcastDice: '1d4' }, { time: 'bonus', components: ['V'], desc: 'Up to six creatures regain 1d4 + your spellcasting modifier hit points.' }),
  protectionFromEnergy: sp('Protection from Energy', 3, 'abjuration', [CLERIC, DRUID, RANGER, SORC, WIZ], { type: 'buff', chooseDamageType: ['acid', 'cold', 'fire', 'lightning', 'thunder'], effect: { name: 'Protection from Energy', minutes: 60 } }, { range: 'touch', ...conc('1 hour'), desc: 'The target resists one damage type: acid, cold, fire, lightning or thunder.' }),
  removeCurse: sp('Remove Curse', 3, 'abjuration', [CLERIC, PALADIN, WARLOCK, WIZ], utility, { range: 'touch', desc: 'All curses on a creature or object end.' }),
