  slow: sp('Slow', 3, 'transmutation', [SORC, WIZ], { type: 'save', save: 'wis', area: { shape: 'cube', size: 40 }, maxTargets: 6, onFail: { name: 'Slowed', speedMultiplier: 0.5, acBonus: -2, dexSaveBonus: -2, saveEnds: 'wis', rounds: 10 } }, { range: 120, components: ['V', 'S', 'M'], ...conc('1 minute'), desc: 'Up to six creatures make Wisdom saves or have halved speed and -2 to AC and Dexterity saves.' }),
  speakWithDead: sp('Speak with Dead', 3, 'necromancy', [BARD, CLERIC], utility, { range: 10, components: ['V', 'S', 'M'], duration: '10 minutes', desc: 'A corpse answers up to five questions.' }),
  spiritGuardians: sp('Spirit Guardians', 3, 'conjuration', [CLERIC], { type: 'aura', radius: 15, save: 'wis', damage: { dice: '3d8', type: 'radiant' }, halfOnSave: true, upcastDice: '1d8', enemiesOnly: true, slowEnemies: true }, { range: 'self', components: ['V', 'S', 'M'], ...conc('10 minutes'), desc: 'Spirits in a 15-foot radius deal 3d8 radiant damage (Wisdom save for half) to enemies that enter or start there.' }),
  stinkingCloud: sp('Stinking Cloud', 3, 'conjuration', [BARD, SORC, WIZ], { type: 'zone', area: { shape: 'sphere', size: 20 }, save: 'con', onFailZone: { name: 'Retching' }, rounds: 10 }, { range: 90, components: ['V', 'S', 'M'], ...conc('1 minute'), desc: 'Nauseating gas: creatures starting their turn inside make Constitution saves or lose their action retching.' }),
